// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2016, "10-11", [{"author":"Б. Иомдин","question":"Когда вспоминают типичные русские фамилии, обычно говорят: <em>Иванов</em>, <em>Петров</em>, … .","choices":["<em>Смирнов</em>","<em>Кузнецов</em>","<em>Сидоров</em>","<em>Фёдоров</em>","<em>Соболев.</em>"],"key":"В","review":["Три привычные фамилии","Вспомни, как называют условных людей в примерах, когда их настоящие фамилии не важны.","Привычная тройка — «Иванов, Петров, Сидоров». Последним здесь называют Сидорова."]},{"author":"П. Аркадьев","question":"Какой из этих глаголов может обозначать речь?","choices":["<em>разрезать</em>","<em>порезать</em>","<em>отрезать</em>","<em>нарезать</em>","никакой."],"key":"В","review":["Резкий ответ","Вспомни, как описывают короткий и решительный ответ, которым человек обрывает разговор.","В примере «Он резко отрезал: „Ни за что!“» глагол «отрезать» обозначает реплику."]},{"author":"Б. Иомдин","question":"Какое слово можно понять и как прилагательное, и как глагол?","choices":["<em>славную</em>","<em>милую</em>","<em>дельную</em>","<em>жалую</em>","<em>радую</em>."],"key":"Б","review":["Форма с двумя значениями","Попробуй подставить каждое слово в сочетание «вижу ___ подругу» и отдельно после местоимения «я».","«Милую» означает признак в «милую подругу» и действие в «я милую осуждённого». Это две грамматические формы с одинаковым написанием."]},{"author":"С. Сай","question":"Вставьте слово, пропущенное в цитате из «Писем русского путешественника» Н. М. Карамзина: <em>Не бойтесь: быстрый луч света издали озаряет ваши глаза ― ещё несколько шагов, и вы опять в __________ мире, на берегу журчащей речки, среди прелестных ландшафтов</em>.","choices":["<em>сливочном</em>","<em>подсолнечном</em>","<em>кукурузном</em>","<em>арахисовом</em>","<em>машинном</em>."],"key":"Б","review":["Из темноты в светлый мир","Герои выходят туда, где их снова освещает солнце. Одно из прилагательных буквально означает «под солнцем».","«Подсолнечный мир» — старое выражение о земном мире. Оно подходит к свету, речке и пейзажу в цитате Карамзина."]},{"author":"Л. Фёдорова","question":"Где нужна запятая?","choices":["<em>Здесь есть</em> (...) <em>чем поживиться</em>.","<em>Потом будет</em> (...) <em>что вспомнить</em>.","<em>Это мало</em> (...) <em>кто знает</em>.","<em>Лучше там</em> (...) <em>где нас нет</em>.","<em>Всегда есть</em> (...) <em>с чем сравнить</em>."],"key":"Г","review":["Граница придаточной части","Ищи отдельную грамматическую основу после запятой. Сравни её с цельными оборотами «есть что вспомнить» и «мало кто знает».","В «Лучше там, где нас нет» часть «где нас нет» поясняет «там» и отделяется запятой. Остальные примеры содержат цельные сочетания."]},{"author":"А. Пиперски","question":"Какое из этих слов не связано с кораблями?","choices":["<em>боцман</em>","<em>мичман</em>","<em>брахман</em>","<em>штурман</em>","<em>флагман</em>."],"key":"В","review":["Названия людей на корабле","Сравни должности в экипаже и название корабля с названием приверженца индийской религиозной традиции.","Боцман, мичман и штурман относятся к морской службе, флагман может обозначать главный корабль. «Брахман» — представитель жреческой группы в Индии."]},{"author":"Л. Фёдорова","question":"В какой паре существительные имеют сходные значения?","choices":["<em>проходимец</em> и <em>пришелец</em>","<em>пришелец</em> и <em>первопроходец</em>","<em>первопроходец</em> и <em>прохожий</em>","<em>прохожий</em> и <em>проходимец</em>","<em>проходимец</em> и <em>пройдоха</em>."],"key":"Д","review":["Смысл близких слов","Начальные части «про-» и «при-» подсказывают происхождение, но в современном языке важен смысл целого слова.","И «проходимец», и «пройдоха» могут называть ловкого и нечестного человека. «Пришелец», «первопроходец» и «прохожий» называют людей по другим признакам."]},{"author":"Е. Бикмаев","question":"Название какого конкурса синтаксически устроено не так, как остальные?","choices":["<em>Мисс Россия</em>","<em>Мисс Мира</em>","<em>Мисс Вселенная</em>","<em>Мисс Весна</em>","<em>Мисс Земля</em>."],"key":"Б","review":["Падеж в названии конкурса","Прочитай оба слова после «Мисс» как название. Проверь, где второе слово стоит в родительном падеже.","В «Мисс Мира» второе слово имеет форму родительного падежа от «мир». «Россия», «Вселенная», «Весна» и «Земля» стоят в именительном."]},{"author":"А. Пиперски","question":"Даны несколько фрагментов из комедии «Горе от ума» А. С. Грибоедова:\nФамусов. <em>Она не родила, но по расчёту / По</em>(1)<em>моему: должна родить…</em>\n\nФамусов. <em>А? как по</em>(2)<em>вашему? по</em>(3)<em>нашему ― смышлён.\nУпал он больно, встал здорово.</em>\n\nЧацкий. <em>Ну, образ жизни ваш каков? / Без горя нынче? без печали?</em>\nМолчалин. <em>По</em>(4)<em>прежнему-с.</em>\nЧацкий. <em>А прежде как живали?</em>\n\nВ каком из мест, обозначенных цифрой, современная орфография не требует дефиса?","choices":["1","2","3","4","во всех этих местах необходим дефис."],"key":"А","review":["Предлог или приставка","Посмотри, есть ли существительное, к которому по смыслу относится притяжательное местоимение «моему».","В первом фрагменте получается «по моему расчёту» с переставленным «расчёту». Предлог «по» пишется раздельно. «По-вашему», «по-нашему» и «по-прежнему» — наречия с дефисом."]},{"author":"А. Панина","question":"Выражение <em>всеми _______ души</em> значит ‘всем сердцем’<em>.</em> А что здесь пропущено?","choices":["<em>фабрами</em>","<em>фибрами</em>","<em>фижмами</em>","<em>фиксами</em>","<em>фирмами</em>."],"key":"Б","review":["Устойчивое выражение о душе","Пропущенное слово связано с образом душевных волокон. Сравни привычные выражения «всем сердцем» и «всей душой».","Говорят «всеми фибрами души». «Фибра» в прямом значении — волокно, а здесь выражение означает полное и искреннее чувство."]},{"author":"Б. Иомдин и И. Иткин","question":"<em>— ...Этот кальян вым...н...л, или, правду сказать, вым...н...л я у английского путешественника, — он принадлежал Шах-Аббасу.</em> Какие гласные буквы мы пропустили в этой цитате из повести А. А. Бестужева-Марлинского «Лейтенант Белозор»?","choices":["<em>е-и, е-я</em>","<em>е-я, е-и</em>","<em>и-а, е-я</em>","<em>а-и, е-я</em>","<em>е-я, а-и</em>."],"key":"Д","review":["Два поступка с кальяном","Герой сначала описывает честную сделку, а затем с оговоркой поясняет, что в действительности произошло.","«Выменял» значит получил в обмен. «Выманил» — получил хитростью. В цитате по порядку пропущены «е, я» и «а, и»."]},{"author":"Е. Галинская","question":"Даны пять заимствованных слов: <em>фейерверк</em>, <em>бульон</em>, <em>секвойя</em>, <em>парашют</em>, <em>кастаньеты</em>. В каких двух из них имеется орфографическая избыточность?","choices":["<em>фейерверк</em> и <em>бульон</em>","<em>секвойя</em> и <em>парашют</em>","<em>бульон</em> и <em>кастаньеты</em>","<em>фейерверк</em> и <em>секвойя</em>","<em>парашют</em> и <em>кастаньеты</em>."],"key":"Г","review":["Лишнее обозначение звука","В русском письме «е» и «я» после гласной могут обозначать [й] вместе с другой гласной. Поищи, где «й» уже написана перед ними.","Так устроены «фейерверк» и «секвойя»: в них есть «йе» и «йя». Буква «й» дублирует звук, который могла бы обозначить следующая йотированная гласная."]},{"author":"И. Иткин","question":"В каком из этих имён последний гласный раньше был беглым?","choices":["<em>Олег</em>","<em>Игорь</em>","<em>Семён</em>","<em>Яков</em>","<em>Пимен</em>."],"key":"А","review":["Историческая форма имени","Проверь, исчезал ли последний гласный имени при изменении падежа. Можно вспомнить старинные формы имени древнерусского князя.","У имени «Олег» встречались старые формы типа «Ольга», где второй гласный исчезал. В современном склонении «Олега» он сохраняется."]},{"author":"О. Подлесская","question":"В каком отрывке слово <em>что</em> отличается по значению от остальных употреблений?","choices":["<em>Ну что ваш батюшка? всё Английского клоба Старинный, верный член до гроба?</em> (А. С. Грибоедов)","<em>Ну, что соседки? Что Татьяна? / Что Ольга резвая твоя?</em> (А. С. Пушкин)","<em>Что враги? пусть клевещут язвительней, / Я пощады у них не прошу.</em> (Н. А. Некрасов)","<em>«Ну, что ваш внук?» ― / «Писал недавно».</em> (Н. П. Огарёв)","<em>— Что ж лошади? — спросила она вошедшего человека. — Давно готовы-с.</em> (Ф. М. Достоевский)"],"key":"В","review":["Что значит «что»","В четырёх цитатах спрашивают о состоянии или новостях. Найди цитату, в которой говорящий показывает своё безразличие.","У Некрасова «Что враги?» значит «какое мне дело до врагов?». В остальных отрывках действительно интересуются, как обстоит дело."]},{"author":"С. Бурлак","question":"С помощью какой приставки нельзя образовать глагол от глагола?","choices":["<em>из-</em>","<em>без-</em>","<em>в-</em>","<em>от-</em>","<em>под</em>-."],"key":"Б","review":["Приставка и основа глагола","Попробуй подставить приставки к глаголам: «из-» к «мерить», «в-» к «нести», «от-» к «резать».","«Измерить», «внести», «отрезать» и «поднести» образованы от глаголов. «Без-» может входить в глаголы типа «обезводить», однако здесь основа — существительное «вода», а приставка «обез-»."]},{"author":"Е. Бикмаев","question":"В интернете встречается такая осмысленная фраза: <em>Завтра сегодня будет вчера</em>. Какими членами предложения в ней являются слова <em>завтра, сегодня, вчера</em>?","choices":["обстоятельством, подлежащим, частью сказуемого","обстоятельством, частью сказуемого, подлежащим","подлежащим, обстоятельством, частью сказуемого","подлежащим, частью сказуемого, обстоятельством","частью сказуемого, подлежащим, обстоятельством."],"key":"А","review":["Три слова о времени","Подставь вместо «сегодня» выражение «сегодняшний день» и спроси, в какой момент этот день станет вчерашним.","«Сегодня» — подлежащее, «будет вчера» — сказуемое с «вчера» в составе. «Завтра» обозначает время и является обстоятельством."]},{"author":"Е. Бикмаев","question":"В журнале «Наука и жизнь» читаем: <em>Прежде всего, сельское население _________, а в городе существуют сословия ― купечество, ремесленники, чиновники, военные, священники, работники…</em> Какова пятая буква пропущенного девятибуквенного слова, если первые четыре его буквы образуют то же слово, что и последние четыре?","choices":["<em>в</em>","<em>г</em>","<em>м</em>","<em>р</em>","<em>х</em>."],"key":"Г","review":["Девять букв и две половины","Контраст с городскими сословиями подсказывает, что сельское население имеет единый состав. Ищи слово с формой «одно + буква + одно».","В журнале сказано «сельское население однородно». Слово состоит из «одно», «р», «одно». Пятая буква — «р»."]},{"author":"А. Пиперски","question":"Даны названия четырёх эпох в истории итальянского искусства (примерно с 1200 по 1600 год): <em>дученто</em>, <em>кватроченто</em>, <em>треченто</em>, <em>чинквеченто</em>. Расположите их в хронологическом порядке.","choices":["<em>треченто</em>, <em>дученто</em>, <em>кватроченто</em>, <em>чинквеченто</em>","<em>чинквеченто</em>, <em>треченто</em>, <em>кватроченто</em>, <em>дученто</em>","<em>кватроченто</em>, <em>дученто</em>, <em>чинквеченто</em>, <em>треченто</em>","<em>дученто</em>, <em>треченто</em>, <em>кватроченто</em>, <em>чинквеченто</em>","<em>чинквеченто</em>, <em>кватроченто</em>, <em>треченто</em>, <em>дученто</em>."],"key":"Г","review":["Века итальянского искусства","Узнай в названиях итальянские слова для двух, трёх, четырёх и пяти. В каждом названии число указывает на свой век.","От 1200-х до 1500-х годов идут «дученто», «треченто», «кватроченто», «чинквеченто»."]},{"author":"Л. Хесед","question":"<em>Борода ― брада, молодость ― младость</em>... Какое из перечисленных ниже слов никогда не имело в старославянском языке аналога с сочетанием -<em>ра</em>-, -<em>ла</em>- на месте -<em>оро</em>-, -<em>оло</em>-?","choices":["<em>болото</em>","<em>воробей</em>","<em>колосс</em>","<em>порог</em>","<em>холоп</em>."],"key":"В","review":["Старые сочетания в корне","Для русских слов славянского происхождения ищи старые соответствия с одной гласной возле «р» или «л».","Известны «блато», «врабий», «праг», «хлап». «Колосс» пришёл из греческого, и его «оло» не соответствует старославянскому «ла»."]},{"author":"А. Курицына и А. Пиперски","question":"Дан фрагмент из поэмы Гомера «Одиссея» в переводе Василия Жуковского:\n<em>Воды глубокие льются; никто переплыть их не может\nСам; то одним кораблям ____________ возможно.</em>\nКакое слово пропущено?","choices":["<em>крепкоданным</em>","<em>крепкозадным</em>","<em>крепкозданным</em>","<em>крепкосданным</em>","<em>крепкоядным</em>."],"key":"В","review":["Слово о кораблях","В отрывке речь о кораблях, способных выдержать плавание через глубокую воду. Пропущенный эпитет описывает то, как они сделаны.","У Жуковского стоит «крепкозданным», то есть крепко построенным. Часть «здан-» связана со старым «здать» в значении «строить»."]},{"author":"И. Рубанов","question":"Вот три пары оборотов: 1) <em>долго не видя ― недолго видя</em>; 2) <em>долго не слушая ― недолго слушая</em>; 3) <em>долго не думая ― недолго думая</em>. В каких из этих пар оба оборота могут иметь один и тот же смысл?","choices":["таких пар здесь нет","только в 1","только в 2","только в 3","только в 2 и 3."],"key":"Д","review":["Положение «не» в оборотах","Прочитай оба оборота как «делая что-то короткое время». Проверь, в каких случаях отрицание можно отнести к длительности действия.","«Долго не слушая» может значить «послушав недолго», а «долго не думая» — «подумав недолго». «Долго не видя» обычно означает, что зрения или встречи долго не было."]},{"author":"М. Рубинштейн","question":"«Скажешь “кел, кел” (‘приходи, приходи’) — не приходят; скажешь “келме, келме” (‘не приходи, не приходи’) — приходят». Это загадка ногайцев, одного из народов Северного Кавказа. А её отгадка — … .","choices":["глаза","губы","руки","ноги","волосы."],"key":"Б","review":["Загадка о звуках","Произнеси «кел» и «келме» и заметь, какие части рта соприкасаются только во втором слове.","Для звука [м] губы смыкаются, то есть сближаются. В «кел» такого звука нет. Отгадка — губы."]},{"author":"И. Иткин и Л. Хесед","question":"Заполните пропуск в стихотворении Игоря Северянина «Пятицвет»:\n<em>Заберусь на рассвете на серебряный кедр\nЛюбоваться оттуда на маневры эскадр.\nСолнце, утро и море! Как я весело-бодр,\nТочно воздух бездумен, точно мумия мудр.\nКто прославлен орлами — ...</em>","choices":["<em>ослепительно щедр!..</em>","<em>знает таинства недр!..</em>","<em>не попасть тому в кадр!..</em>","<em>обойдётся без пудр!..</em>","<em>ах, тому не до выдр!..</em>"],"key":"Д","review":["Пятый гласный в рифме","В словах «кедр», «эскадр», «бодр», «мудр» меняется гласная перед «др». Пятая строка продолжает тот же ряд.","Использованы гласные «е», «а», «о», «у». В слове «выдр» к ним добавляется «ы», а «др» сохраняется. У Северянина строка заканчивается этим словом."]},{"author":"П. Аркадьев","question":"Какой глагол спрягается не так, как другие?","choices":["<em>опоясать</em>","<em>плясать</em>","<em>сосать</em>","<em>тесать</em>","<em>чесать</em>."],"key":"В","review":["Спряжение похожих глаголов","Поставь глаголы в первое лицо: «я пляшу», «я чешу». Сравни окончания основы.","Получаются «опояшу», «пляшу», «тешу», «чешу» с чередованием «с — ш». В «я сосу» согласная «с» сохраняется."]},{"author":"К. Кноп","question":"В каком из перечисленных ниже слов буквы <em>сч</em> могут читаться не так, как во всех остальных словах?","choices":["<em>счёты</em>","<em>считать</em>","<em>расчёт</em>","<em>счастье</em>","во всех словах из ответов (А)‒(Г) буквы <em>сч</em> всегда читаются одинаково."],"key":"Б","review":["Произношение букв «сч»","Проверь, не совпадают ли по написанию два глагола с разным строением. Приставка и корень могут произноситься раздельно.","«Считать» в значении «вести счёт» обычно начинается со звука [щ’]. В значении «прочитать по меткам, скопировать» слово можно произнести с отдельными [с] и [ч’]."]},{"author":"И. Иткин и С. Крылов","question":"― <em>Я раскрасила его ______ целиком!</em> ― радостно закричала Маша, любуясь на получившуюся картинку. Сколько разных форм местоимения <em>весь</em> можно подставить на место пропуска?","choices":["ни одной","одну","две","три","четыре."],"key":"Г","review":["Согласование с «его»","Подумай, какой предмет или персонажа заменяет «его». Для одушевлённого и неодушевлённого существительных формы могут различаться.","Можно раскрасить «его весь» — например дом, «его всего» — нарисованного кота, или «его всё» — пальто. Получается три формы."]},{"author":"С. Сай","question":"Какая из следующих согласных в корнях нарицательных существительных может чередоваться с <em>ш</em>?","choices":["<em>л</em>","<em>м</em>","<em>н</em>","<em>п</em>","<em>р</em>."],"key":"В","review":["Чередование в корнях","Подбери уменьшительные существительные к словам с разными концами основы и посмотри, где появится «ш».","Сравни «карман» и «кармашек». В корне «карман-» перед уменьшительным суффиксом вариант основы заканчивается на «ш». В паре чередуются «н» и «ш»."]},{"author":"Б. Иомдин","question":"В каком предложении можно однозначно определить вид глагола?","choices":["<em>Многие из них крестились лишь в старости</em>.","<em>Их дети крестились в православную веру</em>.","<em>Переселенцы женились и крестились</em>.","<em>Прохожие быстро и молча крестились</em>.","<em>Некоторые половецкие князья крестились</em>."],"key":"Г","review":["Два значения «креститься»","Различай принять крещение и осенять себя крестным знамением. У этих значений разные видовые возможности.","Прохожие совершали крестное знамение. В этом смысле «креститься» — несовершенного вида, а для завершённого жеста говорят «перекреститься»."]},{"author":"А. Пиперски","question":"В русском языке нет нарицательных существительных мужского рода, которые оканчиваются на … .","choices":["<em>едь</em>","<em>езь</em>","<em>ень</em>","<em>ерь</em>","<em>есь</em>."],"key":"Д","review":["Конец слова и род","Подбери хотя бы по одному нарицательному существительному мужского рода к четырём окончаниям из списка.","Есть «медведь», «крезь» — удмуртский музыкальный инструмент, «олень», «зверь». «Весь» в значении «селение» и «взвесь» — женского рода, мужского существительного на «есь» нет."]},{"author":"А. Пиперски","question":"Даны слова искусственного языка универсаль, изобретённого в 1923–1928 годах Гербертом Муравкиным и Леонидом Василевским: fargu, gema, jortsu, nedo, sama. Установите правильный порядок их переводов на русский язык.","choices":["<em>разрушать</em>, <em>единичный</em>, <em>читать</em>, <em>ночь</em>, <em>маленький</em>","<em>единичный</em>, <em>разрушать</em>, <em>ночь</em>, <em>маленький</em>, <em>читать</em>","<em>маленький</em>, <em>читать</em>, <em>ночь</em>, <em>разрушать</em>, <em>единичный</em>","<em>маленький</em>, <em>разрушать</em>, <em>единичный</em>, <em>ночь</em>, <em>читать</em>","<em>читать</em>, <em>маленький</em>, <em>разрушать</em>, <em>ночь</em>, <em>единичный</em>."],"key":"Д","review":["Слова языка универсаль","В этом искусственном языке противоположные понятия часто получали слова с переставленными частями корня. Сравни русское «день» с формой «nedo».","«Nedo» получено перестановкой частей «deno» — «день», и означает «ночь». Так же «sama» — «единичный», «fargu» — «читать», «jortsu» — «разрушать». «Gema» значит «маленький»."]}], {"year":2016,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2016-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
